(() => {
'use strict';
const content=window.PORTFOLIO_CONTENT,api=window.PortfolioGitHub;
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text)n.textContent=text;if(cls)n.className=cls;return n};
function link(text,url,cls='link'){const valid=api.safeURL(url);if(!valid)return el('span',text);const a=el('a',text,cls);a.href=valid;if(valid.startsWith('https:')){a.target='_blank';a.rel='noopener'}return a}
function tags(values){const n=el('div','','tags');values.forEach(v=>n.append(el('span',v)));return n}
const projectRoot=document.getElementById('ongoing-projects');
for(const p of projectRoot?content.projects:[]){const n=el('article','','agent-card');n.dataset.project=p.id;n.append(el('p',p.category,'eyebrow'),el('span',p.status,'status-pill'),el('h3',p.title),el('h4','The business problem'),el('p',p.problem),el('h4','The approach'),el('p',p.approach),tags(p.tags));const actions=el('div','','project-links');actions.dataset.links=p.id;actions.append(link('Explore project & demo ↗',p.page));if(api.repositoryURL(p.repo))actions.append(link('View repository ↗',p.repo));n.append(actions);projectRoot.append(n)}
const publicationRoot=document.getElementById('publication-list');for(const p of publicationRoot?content.publications:[]){const n=el('article','','publication');n.append(el('p',p.label,'eyebrow'),el('h3',p.title));if(p.minutes)n.append(el('span',p.minutes+' min read','read-badge'));n.append(el('p',p.description));n.append(p.url?link(p.action+' ↗',p.url):el('span',p.pending||'Link coming soon','pending-link'));publicationRoot.append(n)}
const speechRoot=document.getElementById('speech-list');for(const [i,s] of (speechRoot?content.speeches:[]).entries()){const n=el('article','','speech');n.append(el('span','0'+(i+1),'speech-number'),el('p',s.theme,'eyebrow'),el('h3',s.title),el('p',s.description),link('Read the speech (.docx) ↗',s.url));speechRoot.append(n)}
const communityRoot=document.getElementById('community-list');for(const s of communityRoot?content.community:[]){const n=el('article','','community-item');n.append(el('p',s.label,'eyebrow'),el('h3',s.title),el('p',s.description));if(s.url)n.append(link(s.action+' ↗',s.url));communityRoot.append(n)}
const credentialRoot=document.getElementById('credential-list');const credentials=content.credentials.filter(c=>api.credentialIsCurrent(c));if(credentialRoot&&credentials.length){credentialRoot.replaceChildren();for(const c of credentials){const n=el('article','','credential');n.append(el('h5',c.title),el('p',c.issuer+' · '+(c.nonExpiring?'No expiration':'Valid through '+new Date(c.expiresAt).toLocaleDateString())),link('Verify credential ↗',c.url));credentialRoot.append(n)}}
const achievements=content.toastmastersAchievements.filter(a=>a.verified===true&&a.title);if(speechRoot&&achievements.length){const n=el('div','','toastmasters-achievements');n.append(el('h3','Toastmasters achievements'));for(const a of achievements)n.append(el('p',a.title+(a.awardedAt?' · '+a.awardedAt:'')));speechRoot.after(n)}
const githubRoot=document.getElementById('github-projects'),githubStatus=document.getElementById('github-status'),refreshButton=document.getElementById('github-refresh');
function renderRepos(repos){if(githubRoot){githubRoot.replaceChildren();for(const r of repos){const card=el('article','','repo-card');card.append(el('p','GITHUB / PROJECT REPOSITORY','eyebrow'),el('h3',r.name.replace(/[-_]/g,' ')),el('p',r.description||'Explore project documentation and source on GitHub.'));if(r.language)card.append(tags([r.language,...(r.topics||[]).slice(0,3)]));if(r.pushed_at&&!Number.isNaN(Date.parse(r.pushed_at)))card.append(el('p','Repository activity: '+new Date(r.pushed_at).toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'}),'small'));card.append(link('View source & documentation ↗',r.html_url));if(r.homepage&&api.safeURL(r.homepage)?.startsWith('https:'))card.append(link('Visit project ↗',r.homepage));githubRoot.append(card)}}
for(const p of content.projects){const area=document.querySelector(`[data-links="${p.id}"]`);if(!area)continue;area.querySelector('[data-repo-link]')?.remove();let match;try{match=repos.find(r=>new RegExp(p.match,'i').test(r.name))}catch{}if(match&&!p.repo){const a=link('View repository ↗',match.html_url);a.dataset.repoLink='true';area.append(a)}}}
let cached=[];const cacheKey='jyoti-github-'+content.github.username;try{const saved=JSON.parse(localStorage.getItem(cacheKey));if(saved?.username===content.github.username&&Array.isArray(saved.repositories))cached=api.selectRepositories(saved.repositories,content.github)}catch{}
async function refreshGitHub(){if(!githubStatus)return;if(!content.github.username){githubStatus.textContent='Selected projects in development. Repository links will appear as the projects are connected.';return}if(cached.length)renderRepos(cached);githubStatus.textContent=cached.length?'Showing saved projects while checking GitHub…':'Loading projects from GitHub…';try{const result=await api.fetchRepositories(content.github);renderRepos(result.repositories);cached=result.repositories;githubStatus.textContent=cached.length?'Public project repositories · Updated '+new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}):'No matching public repositories are available yet.';try{localStorage.setItem(cacheKey,JSON.stringify({username:content.github.username,repositories:cached}))}catch{}}catch(error){githubStatus.textContent=(cached.length?'Showing saved projects. ':'')+error.message}}
if(githubStatus){refreshGitHub();if(content.github.username)setInterval(refreshGitHub,Math.max(5,content.github.refreshMinutes||15)*60000)}if(refreshButton){refreshButton.addEventListener('click',refreshGitHub);refreshButton.hidden=!content.github.username}
const menu=document.getElementById('menu-toggle'),nav=document.getElementById('main-nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('is-open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');nav.classList.remove('is-open')}));
})();

// Portrait depth: gentle tilt and parallax that follow the pointer (desktop, motion allowed)
(()=>{const hero=document.querySelector('.hero'),fig=hero&&hero.querySelector('figure.portrait');if(!fig||matchMedia('(prefers-reduced-motion: reduce)').matches||!matchMedia('(hover: hover)').matches)return;let raf=0;const set=(x,y)=>{cancelAnimationFrame(raf);raf=requestAnimationFrame(()=>{fig.style.setProperty('--tx',x.toFixed(3));fig.style.setProperty('--ty',y.toFixed(3))})};hero.addEventListener('pointermove',e=>{const r=fig.getBoundingClientRect();set(Math.max(-1,Math.min(1,(e.clientX-r.left)/r.width-.5)),Math.max(-1,Math.min(1,(e.clientY-r.top)/r.height-.5)))});hero.addEventListener('pointerleave',()=>set(0,0))})();
